E, CREATE_DEPT, DEAL_REGIST_DATE,IS_ASSET_SUB,REF_TRADESEQNO, ASSET_METHOD,RIVAL_PARTY_TYPE,SUMIT_SEQ, PROD_REGIST_CODE, SUBMIT_FEEDBACK_MSG, INVEST_APPROVER_ID, INVEST_APPROVER_NAME, INVEST_TRADER_ID, INVEST_TRADER_NAME, rank() over (partition by TRADE_CODE order by ifnull(update_time,create_time) desc) ranknum from CHB_INVEST_TRADE_SUB_HIS his
