delete from CHB_INVEST_TRADE_SUB_HIS where 1 =1 and HIS_NO in ( select t.HIS_NO from ( select a.HIS_NO from ( SELECT @rownum:=@rownum+1 `rownum`, a.HIS_NO, IF( @ASSET_CODE = a.ASSET_CODE, @rank := @rank + 1, @rank := 1 ) AS myrank, @ASSET_CODE := a.ASSET_CODE FROM ( SELECT * FROM CHB_INVEST_TRADE_SUB_HIS ORDER BY ASSET_CODE,ifnull( UPDATE_TIME, CREATE_TIME ) DESC) a, ( SELECT @rownum := 0, @FINPROD_ID := NULL, @rank := 0 )b where 1=1
select #{regist.tradeCode,jdbcType=VARCHAR}from dual
)a where 1=1 limit 1 )t)

